package org.transittr;
import android.content.*;import android.graphics.*;import android.view.*;import android.os.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** Small raster map: only visible tiles, 7-day disk cache, bounded RGB565 memory, no WebView. */
public final class OsmMapView extends View {
 public interface Selection {void selected(String title,String detail);}
 private Selection selection;private final Paint paint=new Paint(3);private final Handler main=new Handler();private final ExecutorService pool;private final File disk;private final int capacity;private final LinkedHashMap<String,Bitmap> memory=new LinkedHashMap<String,Bitmap>(24,.75f,true);private final HashSet<String> pending=new HashSet<String>(),visible=new HashSet<String>();private final LinkedHashMap<String,Long> failedUntil=new LinkedHashMap<String,Long>();private volatile boolean closed;private boolean paused,userMoved,metro=true;private double lat=39.9255,lon=32.8538;private int zoom=13,tilesLoaded,failures;private float downX,downY,lastX,lastY;private boolean moved;private final float density;private final ScaleGestureDetector pinch;
 private ArrayList<JourneyData.RailLine> rail=new ArrayList<JourneyData.RailLine>();private ArrayList<JourneyData.Vehicle> vehicles=new ArrayList<JourneyData.Vehicle>();
 public OsmMapView(Context context){super(context);density=getResources().getDisplayMetrics().density;capacity=Build.VERSION.SDK_INT<11?6:40;pool=Executors.newFixedThreadPool(Build.VERSION.SDK_INT<11?1:2);disk=new File(context.getCacheDir(),"osm-v1");disk.mkdirs();setContentDescription("OpenStreetMap haritası. Sürükle, iki parmakla veya artı eksiyle yakınlaştır. Araç ve istasyon ayrıntısına dokun.");pinch=new ScaleGestureDetector(context,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScale(ScaleGestureDetector d){if(d.getScaleFactor()>1.18f){changeZoom(1);return true;}if(d.getScaleFactor()<.84f){changeZoom(-1);return true;}return false;}});}
 private float dp(float n){return n*density;}private static double wx(double lon,int z){return(lon+180)/360*(256L<<z);}private static double wy(double lat,int z){double s=Math.sin(Math.max(-85.0511,Math.min(85.0511,lat))*Math.PI/180);return(.5-Math.log((1+s)/(1-s))/(4*Math.PI))*(256L<<z);}private float x(double longitude){return(float)(wx(longitude,zoom)-wx(lon,zoom)+getWidth()/2);}private float y(double latitude){return(float)(wy(latitude,zoom)-wy(lat,zoom)+getHeight()/2);}
 public void setSelection(Selection s){selection=s;}public int loadedTileCount(){return tilesLoaded;}public int vehicleCount(){return vehicles.size();}public int zoomLevel(){return zoom;}
 public void center(double a,double b,int z){lat=a;lon=b;zoom=Math.max(4,Math.min(18,z));userMoved=false;invalidate();}public void changeZoom(int by){zoom=Math.max(4,Math.min(18,zoom+by));userMoved=true;invalidate();}public void metro(boolean value){metro=value;invalidate();}
 public void lines(ArrayList<JourneyData.RailLine> lines){rail=new ArrayList<JourneyData.RailLine>(lines);invalidate();}
 public void positions(ArrayList<JourneyData.Vehicle> rows,boolean fit){vehicles=new ArrayList<JourneyData.Vehicle>();for(JourneyData.Vehicle v:rows)if(v.hasPosition())vehicles.add(v);if(fit&&!vehicles.isEmpty()){double a=90,b=-90,c=180,d=-180;for(JourneyData.Vehicle v:vehicles){a=Math.min(a,v.lat);b=Math.max(b,v.lat);c=Math.min(c,v.lon);d=Math.max(d,v.lon);}fit(a,b,c,d);}invalidate();}
 public void focus(JourneyData.RailLine line){double a=90,b=-90,c=180,d=-180;for(JourneyData.Station s:line.stations){a=Math.min(a,s.lat);b=Math.max(b,s.lat);c=Math.min(c,s.lon);d=Math.max(d,s.lon);}if(a<=b)fit(a,b,c,d);}
 private void fit(double minLat,double maxLat,double minLon,double maxLon){lat=(minLat+maxLat)/2;lon=(minLon+maxLon)/2;int w=Math.max(180,getWidth())-80,h=Math.max(160,getHeight())-80;zoom=15;while(zoom>7&&(wx(maxLon,zoom)-wx(minLon,zoom)>w||wy(minLat,zoom)-wy(maxLat,zoom)>h))zoom--;userMoved=false;invalidate();}
 private void tile(final String key,final int z,final int tx,final int ty){synchronized(memory){if(closed||paused||memory.containsKey(key)||pending.contains(key)||pending.size()>32)return;Long retry=failedUntil.get(key);if(retry!=null&&retry.longValue()>System.currentTimeMillis())return;pending.add(key);}pool.execute(new Runnable(){public void run(){File file=new File(disk,key.replace('/','_')+".png");boolean failed=false;try{synchronized(memory){if(closed||paused||!visible.contains(key))return;}byte[] bytes=null;boolean downloaded=false;if(file.exists()&&System.currentTimeMillis()-file.lastModified()<7L*86400000L){FileInputStream in=new FileInputStream(file);try{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>262144)throw new IOException("Tile cache sınırı");out.write(b,0,n);}bytes=out.toByteArray();}finally{in.close();}}if(bytes==null){bytes=MapHttp.request("https://tile.openstreetmap.org/"+z+"/"+tx+"/"+ty+".png",null,"",262144);if(bytes.length>262144)throw new IOException("Tile sınırı");downloaded=true;}
 BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,bounds);if(bounds.outWidth!=256||bounds.outHeight!=256)throw new IOException("Geçersiz harita karosu");BitmapFactory.Options options=new BitmapFactory.Options();options.inPreferredConfig=Bitmap.Config.RGB_565;Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(bitmap==null)throw new IOException("Harita karosu okunamadı");if(downloaded){File tmp=new File(file+".tmp");FileOutputStream out=new FileOutputStream(tmp);try{out.write(bytes);}finally{out.close();}if(!tmp.renameTo(file))tmp.delete();}synchronized(memory){if(!closed){failedUntil.remove(key);memory.put(key,bitmap);while(memory.size()>capacity)memory.remove(memory.keySet().iterator().next());tilesLoaded++;}}
 }catch(Exception e){failures++;failed=true;file.delete();synchronized(memory){failedUntil.put(key,Long.valueOf(System.currentTimeMillis()+30000));while(failedUntil.size()>128)failedUntil.remove(failedUntil.keySet().iterator().next());}}finally{synchronized(memory){pending.remove(key);}if(!closed)main.postDelayed(new Runnable(){public void run(){if(!closed)invalidate();}},failed?30000:0);}}});}
 protected void onDraw(Canvas canvas){super.onDraw(canvas);canvas.drawColor(0xffe8eae6);double cx=wx(lon,zoom),cy=wy(lat,zoom);int left=(int)Math.floor((cx-getWidth()/2)/256),right=(int)Math.floor((cx+getWidth()/2)/256),top=(int)Math.floor((cy-getHeight()/2)/256),bottom=(int)Math.floor((cy+getHeight()/2)/256),n=1<<zoom;ArrayList<int[]> needed=new ArrayList<int[]>();synchronized(memory){visible.clear();for(int a=left;a<=right;a++)for(int b=top;b<=bottom;b++){if(b<0||b>=n)continue;int tx=((a%n)+n)%n;String key=zoom+"/"+tx+"/"+b;visible.add(key);Bitmap image=memory.get(key);float px=(float)(a*256-cx+getWidth()/2),py=(float)(b*256-cy+getHeight()/2);if(image!=null)canvas.drawBitmap(image,px,py,null);else{paint.setColor(0xffdde1db);paint.setStrokeWidth(1);canvas.drawLine(px,py,px+256,py,paint);needed.add(new int[]{zoom,tx,b});}}}
 if(metro)for(JourneyData.RailLine line:rail){int color;try{color=Color.parseColor(line.color);}catch(Exception e){color=0xff1d5fbf;}paint.setColor(color);paint.setStrokeWidth(dp(3));paint.setStyle(Paint.Style.STROKE);Path path=new Path();boolean first=true;for(JourneyData.Station s:line.stations){if(first){path.moveTo(x(s.lon),y(s.lat));first=false;}else path.lineTo(x(s.lon),y(s.lat));}canvas.drawPath(path,paint);paint.setStyle(Paint.Style.FILL);for(JourneyData.Station s:line.stations){float a=x(s.lon),b=y(s.lat);if(a<-dp(10)||b<-dp(10)||a>getWidth()+dp(10)||b>getHeight()+dp(10))continue;paint.setColor(0xffffffff);canvas.drawCircle(a,b,dp(4),paint);paint.setStyle(Paint.Style.STROKE);paint.setColor(color);paint.setStrokeWidth(dp(1.5f));canvas.drawCircle(a,b,dp(4),paint);paint.setStyle(Paint.Style.FILL);if(zoom>=15){paint.setColor(0xff202322);paint.setTextSize(dp(11));canvas.drawText(s.name,a+dp(7),b-dp(5),paint);}}}
 for(JourneyData.Vehicle v:vehicles){float a=x(v.lon),b=y(v.lat);if(a<-dp(20)||b<-dp(20)||a>getWidth()+dp(20)||b>getHeight()+dp(20))continue;if(v.estimated){drawTrain(canvas,a,b,v.direction);continue;}boolean stale=v.observedAt>0&&System.currentTimeMillis()-v.observedAt>180000;paint.setColor(0xffffffff);canvas.drawCircle(a,b,dp(11),paint);paint.setColor(stale?0xff6b6b6b:0xff1d5fbf);canvas.drawRoundRect(new RectF(a-dp(8),b-dp(10),a+dp(8),b+dp(10)),dp(4),dp(4),paint);paint.setColor(0xffffffff);canvas.drawRoundRect(new RectF(a-dp(5),b-dp(6),a+dp(5),b+dp(1)),dp(1),dp(1),paint);canvas.drawCircle(a-dp(3),b+dp(6),dp(1.2f),paint);canvas.drawCircle(a+dp(3),b+dp(6),dp(1.2f),paint);}
 paint.setColor(0xeeffffff);canvas.drawRect(getWidth()-dp(194),getHeight()-dp(24),getWidth(),getHeight(),paint);paint.setColor(0xff414540);paint.setTextSize(dp(11));canvas.drawText("© OpenStreetMap contributors",getWidth()-dp(188),getHeight()-dp(8),paint);if(tilesLoaded==0){paint.setColor(0xddffffff);canvas.drawRect(dp(10),dp(10),getWidth()-dp(10),dp(39),paint);paint.setColor(0xff424742);paint.setTextSize(dp(12));canvas.drawText(failures>0?"Harita alınamadı · bağlantıyı kontrol et":"OpenStreetMap yükleniyor…",dp(20),dp(29),paint);}for(int[] t:needed)tile(t[0]+"/"+t[1]+"/"+t[2],t[0],t[1],t[2]);}
 private void drawTrain(Canvas canvas,float x,float y,int direction){paint.setColor(0xffffffff);canvas.drawCircle(x,y,dp(11),paint);paint.setColor(0xff141414);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(dp(2));canvas.drawRoundRect(new RectF(x-dp(7),y-dp(9),x+dp(7),y+dp(7)),dp(3),dp(3),paint);canvas.drawLine(x-dp(4),y+dp(7),x-dp(6),y+dp(10),paint);canvas.drawLine(x+dp(4),y+dp(7),x+dp(6),y+dp(10),paint);paint.setStyle(Paint.Style.FILL);canvas.drawRect(x-dp(4),y-dp(5),x+dp(4),y,paint);Path arrow=new Path();float side=x+dp(direction>0?12:-12);arrow.moveTo(side,y-dp(3));arrow.lineTo(side+dp(direction>0?4:-4),y);arrow.lineTo(side,y+dp(3));arrow.close();canvas.drawPath(arrow,paint);}
 public boolean onTouchEvent(MotionEvent e){pinch.onTouchEvent(e);switch(e.getAction()&255){case MotionEvent.ACTION_DOWN:downX=lastX=e.getX();downY=lastY=e.getY();moved=false;getParent().requestDisallowInterceptTouchEvent(true);return true;case MotionEvent.ACTION_MOVE:float dx=e.getX()-lastX,dy=e.getY()-lastY;if(Math.abs(e.getX()-downX)+Math.abs(e.getY()-downY)>dp(6))moved=true;if(e.getPointerCount()==1){double nx=wx(lon,zoom)-dx,ny=wy(lat,zoom)-dy,size=256L<<zoom;lon=nx/size*360-180;lat=Math.toDegrees(Math.atan(Math.sinh(Math.PI*(1-2*ny/size))));lat=Math.max(-85,Math.min(85,lat));userMoved=true;invalidate();}lastX=e.getX();lastY=e.getY();return true;case MotionEvent.ACTION_UP:if(!moved)select(e.getX(),e.getY());return true;}return true;}
 private void select(float px,float py){if(py>getHeight()-dp(25)&&px>getWidth()-dp(200)){try{getContext().startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://www.openstreetmap.org/copyright")));}catch(Exception ignored){}return;}for(JourneyData.Vehicle v:vehicles)if(Math.hypot(x(v.lon)-px,y(v.lat)-py)<dp(22)){if(selection!=null)selection.selected(v.line+" · "+v.name,v.estimated?v.estimateDetail:"Son kaynak konumu: "+(v.sourceTime.length()>0?v.sourceTime:"Zaman belirtilmedi")+"\n"+v.eta);return;}if(metro)for(JourneyData.RailLine line:rail)for(JourneyData.Station s:line.stations)if(Math.hypot(x(s.lon)-px,y(s.lat)-py)<dp(17)){if(selection!=null)selection.selected(line.id+" · "+s.name,"Metro istasyonu · canlı tren konumu değildir");return;}}
 public void pause(boolean value){paused=value;if(!value)invalidate();}public void close(){closed=true;pool.shutdownNow();main.removeCallbacksAndMessages(null);synchronized(memory){memory.clear();pending.clear();visible.clear();failedUntil.clear();}}
}
